) AS (
  VALUES 
    (254::BIGINT, 'Excelente profesor, es muy claro con la materia. El curso en sí es muy pesado. Las tareas y proyectos sí son muy largos, así que busque un buen grupo de trabajo si no quiere andarla palmando de más. Uno de los mejores profesores de la escuela. Califica justamente y da buena retroalimentación'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2024-06-04T00:00:00+00:00'::TIMESTAMPTZ, '4e4daff8fbf4aa02cf5045d52a8274d541347cbde512ea5bf2182362c3f1a008'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2023-10-31T00:00:00+00:00'::TIMESTAMPTZ, '05d03d41094100d70ae281cb9e75517c879c9a9132403f0346c1148afd70bd6d'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Un profesor increíble, explica muy bien todo, es bastante claro y en consulta guía mucho, por otro lado, sus tareas y exámenes son algo rudos (pero pasables) y en todos los laboratorios hay que hacer bitácoras (a mano)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-07-13T00:00:00+00:00'::TIMESTAMPTZ, '8cb5c33cf6470e961eae5cf328b37385aa5a3c4ad0de9ce95f18f978294af0db'::TEXT, ARRAY[941]::BIGINT[]),
    (254::BIGINT, 'Muy buen profe, el curso es un poco pesado pero si le pone bastante pasa, el profe ayuda mucho y califica justo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'c1605684d95a00d59b79cb2359684476571506b9902e6f6074576c4c22af985c'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'De lo mejor que tiene mante, el curso es durisimo, hay muchas tareas, pero lo hizo dinamico y sus clases no son aburridas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'c9b6677a5291bca567ba02fabafb85bf23ab06fd722010db140fdc31379b7133'::TEXT, ARRAY[986]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2022-10-11T00:00:00+00:00'::TIMESTAMPTZ, '3f6da48845f2c3978cc05f23690b4ead5ed2e16d8b350425e103727141b69cfb'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Excelente profesor, cumple con el programa del curso, domina la materia a la perfección y ayuda mucho al estudiante, ya sea realizando el laboratorio o con problemas en la teoría, califica justo y su actitud motiva al estudiante a ir a clases ADEMAS ES GUAPO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Da crédito extra']::TEXT[], '2021-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'fe567bffce28e34044a161bec0869aa8889390fc0f2e9818c917daf48532e1cc'::TEXT, ARRAY[941]::BIGINT[]),
    (254::BIGINT, 'Excelente, super recomendado...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-08-06T00:00:00+00:00'::TIMESTAMPTZ, 'ca939df405950f2f2b3fd5d50ab35ab3f33393037b4258b74fbdfec2e4a0549c'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'El curso en sí es pesado, pero el profe explica bien y es justo para calificar, también ayuda en consulta. Las tareas y los quices son fuertes. Con el proyecto hay que tener cuidado en los detalles, es mejor buscar uno de semestres anteriores y guiarse.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2021-07-19T00:00:00+00:00'::TIMESTAMPTZ, 'f3bbde9dc560b71dc8cbf52c289ad849646f4626a7f853c814bc2534908f3885'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Explica bien, la materia no es dificil pero deja muchas tareas lo cual es demandante'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'a8aff3ca18a7632a2b5c0aa2228059b1471ff1c5a1d15945d25ed84c2cd2f825'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Muy buen profesor, contesta rápido los mensajes y te explica las veces que sean necesarias. Los quices y examenes son fáciles, aunque si hay que repasar la materia. Hay que realizar bitácora todas las semanas lo cual es un poco cansado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a8ecd9c261ee983c4380a63101b4a8d245ed3398886688270a11e0f18e5cb1aa'::TEXT, ARRAY[943]::BIGINT[]),
    (254::BIGINT, 'Aburre un poco en clases. Se preocupa por el aprendizaje de los estudiantes y es flexible. Las tareas y el proyecto ayudan mucho a subir la nota. Los examenes suelen ser del libro o de examenes de años pasados'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-21T00:00:00+00:00'::TIMESTAMPTZ, '722895e290bcd843c7ab06d6508786521d84b5f11e050cf9ad7b4fd6fbc8fc35'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'El curso en sí tiene mucha materia y el profesor solo llega a leer las diapositivas. Es excelente persona y en consulta ayuda. La evaluación del curso ayuda bastante al estudiante'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-14T00:00:00+00:00'::TIMESTAMPTZ, '51c46f0743a49ce1f9dc3ee28fa6d9a8b9ad535ae3aa600a62c19c2eb089b63c'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Excelente profesor, cumple con el programa del curso, domina la materia a la perfección y ayuda mucho al estudiante, ya sea realizando el laboratorio o con problemas en la teoría, califica justo y su actitud motiva al estudiante a ir a clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, '035a9b2a9158fdaf96c40dce6f38a5805fad2cb4acc95a799a897379f8efc88f'::TEXT, ARRAY[941]::BIGINT[]),
    (254::BIGINT, 'Muy pura vida, la clase es super pesada y el profe solo llega a leer las presentaciones y no hace ejercicios de ejemplo. En los examenes y quices hace preguntas muy específicas y conceptuales, por lo que hay que estudiar mucho y asimilar muy bien la materia. La distribución de porcentajes ayuda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, '4bc7f901feec484044099259b91fde4d705053feb29d77e24b1a7ff5d5dea4d3'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'El curso es increíblemente pesado y el estilo monótono del profe no ayuda a poner atención. Solo lee las presentaciones y no hace nada de ejercicios. Los exámenes son pesados. Depende del día puede ayudar con la nota.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, '8ed38037f0483366387faa86fa00150fc66b5bf80463309c4a335da80bbfce6f'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Explica bien, pero la clase se hace larga porque es en la pura mañana y es muy teórica, casi no se hacen ejercicios en clase. Por cómo están distribuidos los porcentajes, es difícil quedarse aunque a uno le vaya mal en los exámenes, además el profe es generoso con la nota si ve que uno le puso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2018-11-22T00:00:00+00:00'::TIMESTAMPTZ, 'f7380ad7d9a38867606863606f1b18c91f08ae264cc2c26ca7285f89010fd486'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'No explica tan mal, el problema es que el curso es bastante pesado y hay mucho que cubrir, con tutorías se complementa bastante igual con el lab'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'fab5746a7fb6ceda4a7f0c0a38a052d553bfa39cb28ce33e82afb59aeed0fa8d'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'El curso es difícil y da mucho sueño. Aún no se sabe si es la hora o el profe. Si usted le pone el profe lo valora. Tenga interés. Con el lab se complementa lo que no entiende'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'a30ea3f3c2882b0c1131d809f81a2e8cbbf8ce64c74d395939c282ba3000a50c'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Las clases son muy aburridas. Se debe estudiar del libro para poder comprender la materia ya que la explicación de dl no es muy clara. Es necesario hacer mucha práctica fuera de clases para pasar los exámenes'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-28T00:00:00+00:00'::TIMESTAMPTZ, '0a5ba1c12a3027a0f83ea5b69b7a96d3d4ec66b43ebec652df89a259f80eb35b'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2017-08-10T00:00:00+00:00'::TIMESTAMPTZ, 'a2c500c95ca097edcc92bbf084c8e416473ff76915d230dfff4de949983e3c9a'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'El profe es bueno para ser de Mante. Los exámenes son duros, y los quices son acorde a la materia pero no son fáciles. Se preocupa por uno e intenta aclarar dudas. Es buena persona y ayuda en consulta. Pero hay que estudiar bastante e ir a todas las clases para poder pasar bien, no es imposible'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'eda57c2b1fd6ce3103cd22b56b323e90ed6cf2bdc9ca61cb5ee7f6d75494065f'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Las clases son aburridas, y confusas, es mejor estudiar la materia del libro y complementar con las clases y tutorías. Aun así, el profesor es paciente con uno. Los exámenes son complicados.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'b2a9c92e975092188246552ade5624e1ca0196f2be56190d3339c4d4faf3b2d1'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Muy buena gente, explica bastante bien y en consulta ayuda muchísimo! Las clases son un poco aburridas, quices de acuerdo a lo visto y los exámenes un poco más retadores'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '9c47b1f02a315d090fcb1789b38404958a0e43e2cdf1d4a5270bdd491bf085e8'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'En general explica bien, pero las clases son sumamente aburridas por lo que cuesta ponerle atención se preocupa porque el estudiante aprenda y el segundo examen es bastante rudo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8af11f5ccc5e3ed6616646b52ec178bea80088ad1f1fab05f7fafe0e25ead301'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'El profesor explica excelente. Los quices son de acuerdo a la materia. Los exámenes son más complicados . No es buena gente.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd804c78137af4c9d0d01b32d8e22305bbb7355dc63e3c83024e02134ca8e51b6'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'f13f14ab8d622416f0df6385a62f4818fdaf62c7befdc5328e50221b958a7969'::TEXT, ARRAY[610]::BIGINT[]),
    (254::BIGINT, 'Es una teja de Profe pero en verano no da consulta ni atiende los correos. De dibujo a mano no explica casi nada. Si no tiene q llevar industrial mejor otra opción porque el exige como si todos lo tendríamos q llevar. No ayuda en nada en verano ni atiende consultas'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '95d35236d7110bd9eaa5167dfc6c3cdf4bfb7aeb42585f4cef620ac28ff93ec9'::TEXT, ARRAY[610]::BIGINT[]),
    (254::BIGINT, 'El profe es buena gente y medio explica bien, pero es demasiado aburrido es imposible no dormirse, el curso se pasa por la forma en la que estan distribuidos los porcentajes'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-02T00:00:00+00:00'::TIMESTAMPTZ, '7a91d4ea4eca64e025e50a0cf4327cc0758a6795a2f964ac549fe7ee73b6536a'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Es aburrido pero explica bien'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '331263406582c6a2f059d5bfa9777c3631ce50ba136f0c52c161a7f8a432c6fa'::TEXT, ARRAY[962]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-15T00:00:00+00:00'::TIMESTAMPTZ, 'c70a284c9353e7d3056209bb22759de86d5f7d1c499211710c93cd8fdcc93ff4'::TEXT, ARRAY[610, 3053]::BIGINT[]),
    (254::BIGINT, 'Uno pasa el curso porque la rúbrica de evaluación así lo permite, pero califica los problemas rudos, quita muchos puntos si no se llega a la respuesta correcta. Es buena gente'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-01T00:00:00+00:00'::TIMESTAMPTZ, '0b03f2fee81957027ddc2983e15af8abd97802bfc5a1a7737618a56e690d21d1'::TEXT, ARRAY[958]::BIGINT[]),
    (254::BIGINT, 'no debe ni donde esta parado'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-23T00:00:00+00:00'::TIMESTAMPTZ, '51786cf0a17665f3c2fd8efc971e2ed750cfe863ac82e4a9ec29d7e29b166f16'::TEXT, ARRAY[1010]::BIGINT[]),
    (254::BIGINT, 'Demasiado pura vida, se aprende. Califica medio suave sin dejar de lado la dificultad del curso. Excelente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '81230a7763abc87c4efa1f5e420779e24092b5b518471164e7c5db4577065fc8'::TEXT, ARRAY[934]::BIGINT[]),
    (254::BIGINT, 'Muy buen profe'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'c575e9bdaeea4cf0db223cd725beb64397b6a48884134d92b9dcca33e551f81e'::TEXT, ARRAY[962]::BIGINT[]),
    (254::BIGINT, 'Muy buen profe, da los cursos donde uno siente que hay que ponerle para pasarlos, pero no los hace sentir imposibles y ayuda bastante'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '8825eb0721faa1fb7a3d05cceae4aa315fd575ffcec30edcdf573ec78329f6df'::TEXT, ARRAY[3053]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '3d03643908ad2b500e490f0968aac4ce43be7fd39f7a7cde45c532f83961533b'::TEXT, ARRAY[610]::BIGINT[]),
    (254::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c5a4990fa8529f62487dc209943dcb04e15fd973d1122715f4f1cdf3bbed6921'::TEXT, ARRAY[934]::BIGINT[]),
    (254::BIGINT, 'Es una teja, le importa que uno de verdad aprenda, no se pone en tanta tontera (como otros profesores que dan la misma materia), está muy conciente que uno no solo está llevando esa materia con él, nivel normal de tareas y explica muy bien'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '113bb0df9089c42fd743f261bd863298abd0b0272b4eb560a4571368eb87bffd'::TEXT, ARRAY[933]::BIGINT[]),
    (254::BIGINT, 'El mae explica maso, califica suave y se preocupa por que los estudiantes aprendan.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '85f1af901a2e35cbf0cf772132cb6f9575a04435cddc086619600db53c4e2919'::TEXT, ARRAY[934]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
